steps.command:
set -e; install -d -m 700 /etc/nginx/tls; install -d -m 755 /app/client-trust; openssl req -x509 -newkey rsa:2048 -nodes -days 365 -subj '/CN=localhost-stage' -keyout /etc/nginx/tls/site-stage.key -out /etc/nginx/tls/site-stage.crt >/dev/null 2>&1; chmod 600 /etc/nginx/tls/site-stage.key; cp /etc/nginx/tls/site-stage.crt /app/client-trust/site-stage.crt; cat > /etc/nginx/conf.d/project.conf <<'EOF'
server {
 listen 8443 ssl;
 server_name localhost;
 ssl_certificate /etc/nginx/tls/site-stage.crt;
 ssl_certificate_key /etc/nginx/tls/site-stage.key;
 root /var/www/main;
 location /dev/ { alias /var/www/dev/; }
}
EOF
rm -f /etc/nginx/sites-enabled/default; nginx -t; nginx; sleep 1; echo 'stage_identity:'; openssl x509 -in /etc/nginx/tls/site-stage.crt -noout -subject -fingerprint -sha256; printf 'stage_https_main='; curl -ks https://localhost:8443/index.html; printf 'stage_https_dev='; curl -ks https://localhost:8443/dev/index.html
